def get_mask_card_number(card_number_full=""):    """функция маскирования номера карты"""    if not card_number_full:  # Проверка на пустую строку        raise ValueError("Аргумент не передан")        return "Аргумент не передан"    card_number = card_number_full.replace(" ", "")    if card_number.isdigit() and len(card_number) == 16:        num_1 = card_number[0:4]        num_2 = card_number[4:6] + "**"        num_3 = "****"        num_4 = card_number[12:16]        mask_card_number = " ".join([num_1, num_2, num_3, num_4])        return mask_card_number    elif len(card_number) < 16:        raise ValueError("Номер карты введен не полностью")        return "Номер карты введен не полностью"    elif len(card_number) > 16:        raise ValueError("Ошибка! Максимум 16 цифр. Попробуйте снова")        return "Ошибка! Максимум 16 цифр. Попробуйте снова"    else:        raise ValueError("Ошибка! Номер карты должен состоять из цифр")        return "Ошибка! Номер карты должен состоять из цифр"# get_mask_card_number(input("Введите номер карты: "))def get_mask_account(account_number_full=""):    """функция маскирования номера счета"""    if not account_number_full:  # Проверка на пустую строку        raise ValueError("Аргумент не передан")        return "Аргумент не передан"    account_number = account_number_full.replace(" ", "")    if account_number.isdigit() and len(account_number) == 20:        mask_account = "**" + account_number[-4:]        return mask_account    elif len(account_number) < 20:        raise ValueError("Номер счета введен не полностью")        return "Номер счета введен не полностью"    elif len(account_number) > 20:        raise ValueError("Ошибка! Максимум 20 цифр. Попробуйте снова")        return "Ошибка! Максимум 20 цифр. Попробуйте снова"    else:        raise ValueError("Ошибка! Номер счета должен состоять из цифр")        return "Ошибка! Номер счета должен состоять из цифр"# get_mask_account(input("Введите номер счета: "))